contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        bool firstReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        bool initReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        bool secondReverted;
        c.SetMinSum(_val); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(
            (firstReverted == false) &&
            (initReverted == false) &&
            (secondReverted == true)
        );
    }
}

