// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        bool firstReverted;
        try c.SetMinSum(_val) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        bool secondReverted;
        try c.SetMinSum(_val) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assertTrue((firstReverted == false) &&
            (initReverted == false) &&
            (secondReverted == true));
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
